package de.rearstudio

import android.media.session.PlaybackState
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

class WidgetRulesTest {
    @Test fun simultaneousEventsAddWidgetsWithoutReplacingClock(){val clock=StudioWidget(kind="clock");val music=StudioWidget(kind="music",condition="music");val charging=StudioWidget(kind="battery",condition="charging");assertEquals(listOf(clock,music,charging),WidgetRules.visible(listOf(clock,music,charging),WidgetEvents(music=true,charging=true)))}
    @Test fun endedMusicRemovesItsWidget(){val w=StudioWidget(kind="music",condition="music");assertTrue(WidgetRules.visible(listOf(w),WidgetEvents()).isEmpty());assertEquals(listOf(w),WidgetRules.visible(listOf(w),WidgetEvents(music=true)))}
    @Test fun notificationRevealsUnderlyingMusicWhenItEnds(){val music=StudioWidget(kind="music",condition="music");val note=StudioWidget(kind="notification",condition="notification",hideBelow=true);val list=listOf(music,note);assertEquals(listOf(note),WidgetRules.visible(list,WidgetEvents(music=true,notification=true)));assertEquals(listOf(music),WidgetRules.visible(list,WidgetEvents(music=true)));assertTrue(WidgetRules.visible(list,WidgetEvents()).isEmpty())}
    @Test fun disabledOverlayCannotHideAnotherWidget(){val base=StudioWidget(kind="clock");val overlay=StudioWidget(kind="notification",enabled=false,hideBelow=true);assertEquals(listOf(base),WidgetRules.visible(listOf(base,overlay),WidgetEvents(notification=true)))}
    @Test fun NonOverlappingWidgetIsKept(){val base=StudioWidget(kind="clock",x=0f,y=0f,w=.2f,h=.2f);val overlay=StudioWidget(kind="notification",x=.5f,y=.5f,w=.2f,h=.2f,hideBelow=true);assertEquals(2,WidgetRules.visible(listOf(base,overlay),WidgetEvents()).size)}
    @Test fun migrationKeepsCoordinatesAndIsIdempotent(){val old=StudioScene.defaults();val first=old.profile("normal").widgets.first();first.x=.41f;old.toUnified();val count=old.profile("normal").widgets.size;old.toUnified();assertEquals(count,old.profile("normal").widgets.size);assertEquals(.41f,old.profile("normal").widgets.first().x,.001f);assertTrue(old.profile("normal").widgets.any{it.kind=="battery"&&it.condition=="charging"});assertTrue(old.profile("normal").widgets.any{it.kind=="notification"&&it.condition=="notification"})}
    @Test fun allNewPropertiesAndFiveFavoritesPersist(){val s=StudioScene.defaults().toUnified();s.favorites[4]=0xff123456.toInt();s.gestures["up"]="dj";s.djEnabled=true;s.profile("normal").widgets.first().apply{condition="music";hideBelow=true;locked=true;action="app:example";target="phone"};val r=StudioScene.parse(s.json());assertTrue(r.unified);assertTrue(r.djEnabled);assertEquals(s.favorites,r.favorites);assertEquals("dj",r.gestures["up"]);assertEquals(s.profile("normal").widgets.first(),r.profile("normal").widgets.first())}
    @Test fun playbackPausedOrStoppedIsNotAnActiveMusicTrigger(){assertFalse(MediaHub.isPlaybackActive(null));assertFalse(MediaHub.isPlaybackActive(PlaybackState.STATE_STOPPED));assertFalse(MediaHub.isPlaybackActive(PlaybackState.STATE_PAUSED));assertTrue(MediaHub.isPlaybackActive(PlaybackState.STATE_PLAYING));assertTrue(MediaHub.isPlaybackActive(PlaybackState.STATE_BUFFERING))}
    @Test fun fourGesturesRespectSystemEdgeStrips(){assertEquals("left",StudioSwipes.direction(700f,200f,300f,205f,976,596));assertEquals("right",StudioSwipes.direction(300f,200f,700f,205f,976,596));assertEquals("down",StudioSwipes.direction(500f,100f,505f,400f,976,596));assertEquals("up",StudioSwipes.direction(500f,400f,505f,100f,976,596));assertNull(StudioSwipes.direction(970f,200f,100f,200f,976,596));assertNull(StudioSwipes.direction(100f,590f,100f,100f,976,596))}
    @Test fun fixturesNeverFabricateMissingScoresOrOtherTeams(){val json=JSONObject("""{"events":[{"idEvent":"1","idHomeTeam":"7","idAwayTeam":"8","strHomeTeam":"A","strAwayTeam":"B","intHomeScore":null,"intAwayScore":null,"idLeague":"4"},{"idEvent":"2","idHomeTeam":"9","idAwayTeam":"10","intHomeScore":"0","intAwayScore":"0"}]}""");val fixtures=HubData.fixtures(json,"7");assertEquals(1,fixtures.size);assertNull(fixtures.first().score);assertTrue(HubData.filtered(fixtures,emptySet()).isEmpty());assertEquals(fixtures,HubData.filtered(fixtures,null));assertEquals(fixtures,HubData.filtered(fixtures,setOf("4")))}
    @Test fun oldVersionOneSceneCanStillBeRead(){val json=JSONObject(StudioScene.defaults().json()).put("version",1).apply{remove("unified");remove("favorites");remove("gestures")};assertFalse(StudioScene.parse(json.toString()).unified)}
}
